#include <assert.h>
#include <stdio.h>

double average(const int *values, size_t count) {
    assert(values != NULL);
    assert(count > 0);

    long sum = 0;
    for (size_t i = 0; i < count; i++) sum += values[i];
    return (double) sum / count;
}

int main(void) {
    int values[] = {4, 6, 8};
    printf("promedio: %.2f\n", average(values, 3));
    return 0;
}
